INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist traceroute6 nur für IPv6-Netze nötig?', 2, '[{"text": "Ja", "correct": true, "because": "Spezifisch für IPv6"}, {"text": "Nein", "correct": false, "because": "traceroute kann IPv6 oft auch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option verhindert DNS-Auflösung bei traceroute?', 3, '[{"text": "-n", "correct": true, "because": "Zeigt nur IP-Adressen"}, {"text": "-m", "correct": false, "because": "Setzt maximale Hops"}, {"text": "-q", "correct": false, "because": "Kontrolliert Abfragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen sind bei traceroute6 nützlich?', 5, '[{"text": "-n", "correct": true, "because": "Keine DNS-Auflösung"}, {"text": "-m 20", "correct": true, "because": "Begrenzt Hops auf 20"}, {"text": "-p", "correct": false, "because": "Port-Angabe, nicht Standard"}, {"text": "-x", "correct": false, "because": "Keine Standardoption"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) -n beschleunigt traceroute. b) traceroute6 nutzt nur ICMPv6.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch UDP möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei traceroute6-Optionen?', 4, '[{"text": "-n", "correct": false, "because": "Vermeidet DNS-Verzögerung"}, {"text": "-m", "correct": false, "because": "Begrenzt Hops"}, {"text": "-z", "correct": true, "because": "Keine Standardoption"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob -n die Ausgabe vereinfacht?', 2, '[{"text": "Ja", "correct": true, "because": "Nur IPs, keine Namen"}, {"text": "Nein", "correct": false, "because": "Vereinfachung ist Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option setzt die maximale Hop-Anzahl auf 15?', 3, '[{"text": "-m 15", "correct": true, "because": "Begrenzt Hops auf 15"}, {"text": "-n 15", "correct": false, "because": "-n ist für DNS"}, {"text": "-q 15", "correct": false, "because": "Abfragen pro Hop"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Effekte haben traceroute6-Optionen?', 5, '[{"text": "-n zeigt IPs direkt", "correct": true, "because": "Keine DNS-Auflösung"}, {"text": "-m begrenzt Pfadlänge", "correct": true, "because": "Maximale Hops"}, {"text": "-n misst Bandbreite", "correct": false, "because": "Nur Ausgabe"}, {"text": "-m verschlüsselt Daten", "correct": false, "because": "Keine Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) -n vermeidet DNS-Abfragen. b) traceroute6 ist nur für IPv4. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "traceroute6 ist IPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für traceroute6?', 4, '[{"text": "-n", "correct": false, "because": "Beschleunigt Ausgabe"}, {"text": "-m", "correct": false, "because": "Kontrolliert Hops"}, {"text": "-y", "correct": true, "because": "Keine Standardoption"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ändert -n die Hop-Anzahl?', 2, '[{"text": "Nein", "correct": true, "because": "Nur DNS-Auflösung"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit -m"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option hilft, traceroute6 schneller zu machen?', 4, '[{"text": "-n", "correct": true, "because": "Keine DNS-Verzögerung"}, {"text": "-m", "correct": false, "because": "Begrenzt nur Hops"}, {"text": "-q", "correct": false, "because": "Reduziert Abfragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass -m die Latenz misst. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "-m begrenzt Hops"}, {"text": "Ja", "correct": false, "because": "Latenz ist Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei traceroute6 für schnelle Ergebnisse?', 3, '[{"text": "-n", "correct": true, "because": "Vermeidet DNS"}, {"text": "-m", "correct": false, "because": "Hops sekundär"}, {"text": "-t", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) -n zeigt nur IPs. b) traceroute6 nutzt immer UDP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ICMPv6 auch möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten traceroute6-Optionen?', 5, '[{"text": "Schnellere Ausgabe", "correct": true, "because": "-n spart DNS"}, {"text": "Kontrolle über Hops", "correct": true, "because": "-m begrenzt"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "Bandbreitenmessung", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei traceroute6-Optionen unwichtig?', 3, '[{"text": "-n", "correct": false, "because": "Beschleunigt"}, {"text": "-m", "correct": false, "because": "Begrenzt Hops"}, {"text": "-x", "correct": true, "because": "Keine Standardoption"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Begrenzt -n die Hops?', 3, '[{"text": "Nein", "correct": true, "because": "Das macht -m"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit -m"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob -n die Latenz beeinflusst?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Ausgabezeit"}, {"text": "Ja", "correct": false, "because": "Keine direkte Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option wähle ich für maximal 10 Hops?', 4, '[{"text": "-m 10", "correct": true, "because": "Begrenzt auf 10 Hops"}, {"text": "-n 10", "correct": false, "because": "-n ist DNS"}, {"text": "-q 10", "correct": false, "because": "Abfragen pro Hop"}]');
